"SI-3(4)": {"statement":[{"prose":"Update malicious code protection mechanisms only when directed by a privileged user."}],"discussion":["Protection mechanisms for malicious code are typically categorized as security-related software and, as such, are only updated by organizational personnel with appropriate access privileges."],"params":[],"related":["CM-5"],"objectives":[{"id":"si-3.4_obj","label":"SI-03(04)","prose":"malicious code protection mechanisms are updated only when directed by a privileged user."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing malicious code protection","list of privileged users on system","system design documentation","malicious code protection mechanisms","records of malicious code protection updates","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developers","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for malicious code protection"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing malicious code protection capabilities"]}],"references":[]},
