"SI-3(6)": {"statement":[{"label":"(a)","prose":"Test malicious code protection mechanisms [Assignment: organization-defined frequency] by introducing known benign code into the system; and"},{"label":"(b)","prose":"Verify that the detection of the code and the associated incident reporting occur."}],"discussion":["None."],"params":[{"id":"SI-03(06)_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to test malicious code protection mechanisms is defined"}],"related":["CA-2","CA-7","RA-5"],"objectives":[{"id":"si-3.6_obj.a","label":"SI-03(06)(a)","prose":"malicious code protection mechanisms are tested [Assignment: organization-defined frequency] by introducing known benign code into the system;"},{"id":"si-3.6_obj.b","label":"SI-03(06)(b)","prose":"","items":[{"id":"si-3.6_obj.b-1","label":"SI-03(06)(b)[01]","prose":"the detection of (benign test) code occurs;"},{"id":"si-3.6_obj.b-2","label":"SI-03(06)(b)[02]","prose":"the associated incident reporting occurs."}]}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing malicious code protection","system design documentation","system configuration settings and associated documentation","test cases","records providing evidence of test cases executed on malicious code protection mechanisms","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for malicious code protection"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing the testing and verification of malicious code protection capabilities"]}],"references":[]},
